    out=[[bg]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=bg and not seen[i][j]:
                c=grid[i][j]; comp=[]; q=deque([(i,j)]); seen[i][j]=True
                while q:
                    y,x=q.popleft(); comp.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and grid[ny][nx]==c:
                                seen[ny][nx]=True; q.append((ny,nx))
                ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
                y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
                area=(y1-y0+1)*(x1-x0+1)
                if len(comp)>=4 and len(comp)>=area*0.6:
                    for y in range(y0,y1+1):
                        for x in range(x0,x1+1):
                            out[y][x]=c
    return out
